// Age Matrix: filter records exactly 3, 7, or 14 days old today
const TARGET_DAYS = [3, 7, 14];
const portalLink = 'https://sites.google.com/view/portail-temara-mall/accueil';

function toE164MA(raw) {
  if (raw == null || raw === '') return '';
  let phone = String(raw).replace(/[\s\-\(\)\.]/g, '');
  if (!phone) return '';
  if (phone.startsWith('+')) return phone;
  if (phone.startsWith('00')) return '+' + phone.slice(2);
  if (phone.startsWith('212')) return '+' + phone;
  if (phone.startsWith('0')) return '+212' + phone.slice(1);
  return '+212' + phone;
}

function daysSince(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  d.setHours(0, 0, 0, 0);
  return Math.round((today - d) / (24 * 60 * 60 * 1000));
}

const DRIP_COPY = {
  3: {
    sms: 'Bonjour [Nom], nous avons remarqué que votre rendez-vous a été annulé ou manqué. Nous serions ravis de vous revoir — reprenez un créneau ici : [Link]',
    subject: 'Nous vous avons manqué — J+3',
    body: 'Il y a 3 jours, votre rendez-vous au cabinet a été annulé ou vous ne vous êtes pas présenté(e). Notre équipe est disponible pour vous aider à replanifier.'
  },
  7: {
    sms: 'Bonjour [Nom], rappel amical : votre place au cabinet est toujours disponible. Reprenez rendez-vous en un clic : [Link]',
    subject: 'Rappel J+7 — Reprenez votre rendez-vous',
    body: 'Une semaine s\'est écoulée depuis votre absence ou annulation. N\'hésitez pas à nous contacter pour choisir un nouveau créneau.'
  },
  14: {
    sms: 'Bonjour [Nom], dernière relance : nous aimerions vous revoir au cabinet. Réservez votre créneau dès maintenant : [Link]',
    subject: 'Dernière relance J+14 — Reprenez rendez-vous',
    body: 'Deux semaines se sont écoulées. Sécurisez une nouvelle date de consultation avant que les disponibilités se remplissent.'
  }
};

const LEAK_STATUSES = new Set(['Annulé', 'No-show']);

const leaks = $input.all().filter(item => {
  const status = (item.json['Statut du RDV'] ?? '').toString().trim();
  return LEAK_STATUSES.has(status);
});

const cohort = leaks.filter(item => {
  const appointmentDate = item.json['Date & Heure du RDV'] ?? item.json['Date Creation'];
  const age = daysSince(appointmentDate);
  return age !== null && TARGET_DAYS.includes(age);
});

return cohort.map(item => {
  const appointmentDate = item.json['Date & Heure du RDV'] ?? item.json['Date Creation'];
  const age = daysSince(appointmentDate);
  const copy = DRIP_COPY[age];
  const nom = item.json['Patient (Nom Complet)'] ?? 'Patient';
  return {
    json: {
      Nom: nom,
      Phone: toE164MA(item.json['Téléphone (WhatsApp)'] ?? ''),
      Email: item.json['Email Contact'] ?? '',
      AgeDays: age,
      Link: portalLink,
      SmsMessage: copy.sms.replace('[Nom]', nom).replace('[Link]', portalLink),
      EmailSubject: copy.subject,
      EmailBody: copy.body
    }
  };
}).filter(item => item.json.Phone);
